import { defineSchedule } from "@grok/agent-sdk/schedules";
import queue from "../channels/queue.js";
import { collectWeek } from "../lib/collect.js";

export default defineSchedule({
  cron: "0 9 * * 1",
  async run(schedule) {
    const week = await collectWeek(schedule.host);
    schedule.waitUntil(
      schedule.receive(queue, {
        message: week.prompt,
        auth: schedule.appAuth,
        target: week,
      }),
    );
  },
});
